def _resolve_page_titles(output: Path, selectors: list[str], query_record: Path | None) -> list[str]:
    projection = json_load(output / "markdown/projection.json")
    pages = projection.get("pages", [])
    title_by_id = {page["id"]: page["title"] for page in pages}
    titles = set(title_by_id.values())
    folded = {title.casefold(): title for title in titles}
    selected: list[str] = []
    for selector in selectors:
        exact = folded.get(selector.casefold())
        if exact:
            selected.append(exact)
            continue
        partial = sorted(title for title in titles if selector.casefold() in title.casefold())
        if len(partial) != 1:
            raise CkbError(f"knowledge-page selector must match one page: {selector}; candidates={partial[:20]}")
        selected.append(partial[0])
    if query_record:
        query = json_load(query_record)
        for page in query.get("selected_pages", []):
            title = page.get("title")
            if title in titles:
                selected.append(title)
        owners = projection.get("entity_owner_pages", {})
        for node in query.get("nodes", []):
            node_id = node.get("id")
            page_id = owners.get(node_id) or (node_id if node_id in title_by_id else None)
            if page_id in title_by_id:
                selected.append(title_by_id[page_id])
        for entity in query.get("selected_entities", []):
            title = entity.get("human_page_title")
            if title in titles:
                selected.append(title)
    return list(dict.fromkeys(selected))

def _source_links_for_titles(output: Path, titles: list[str]) -> list[str]:
    projection = json_load(output / "markdown/projection.json")
    graph = json_load(output / "graph.json")
    page_by_title = {page["title"]: page for page in projection.get("pages", [])}
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    links = []
    for title in titles:
        page = page_by_title.get(title)
        entity = entity_by_id.get(page.get("id")) if page else None
        if not entity or not entity.get("path") or not entity.get("range"):
            continue
        links.append(
            source_markdown_link(
                openers,
                entity["path"],
                int(entity["range"]["start_line"]),
                int(entity["range"]["end_line"]),
            )
        )
    return links

def read_note_body(body_path: Path) -> str:
    """Read and validate one user-authored knowledge-note body."""

    if not body_path.is_file():
        raise CkbError(f"note body does not exist: {body_path}")
    try:
        body = body_path.read_text(encoding="utf-8-sig").strip()
    except UnicodeDecodeError as exc:
        raise CkbError(f"note body must be valid UTF-8: {exc}") from exc
    if not body:
        raise CkbError("note body must not be empty")
    if not contains_chinese_narrative(body):
        raise CkbError("knowledge note descriptions must use Simplified Chinese; English proper nouns and code identifiers are allowed")
    if body.startswith("---\n") or LONG_HEX.search(body):
        raise CkbError("human knowledge notes must omit frontmatter and hash-like identifiers")
    return body

def render_note_text(kind: str, title: str, body: str, linked_titles: list[str], source_links: list[str]) -> str:
    sections = [f"# {title.strip()}", "", f"标签：{TAG_BY_KIND[kind]}", "", body]
    if linked_titles:
        sections.extend(["", "## 相关知识页", "", *[f"- [[{value}]]" for value in linked_titles]])
    if source_links:
        sections.extend(["", "## 源码入口", "", *[f"- {value}" for value in source_links]])
    text = "\n".join(sections).rstrip() + "\n"
    if LONG_HEX.search(text):
        raise CkbError("generated human knowledge note contains a hash-like identifier")
    return text

def selectors_for_changed_paths(output: Path, changed_paths: list[str]) -> list[str]:
    """Map working-tree paths to deterministic owner pages, with repository fallback."""
    selected_paths = {value.replace("\\", "/") for value in changed_paths}
    if not selected_paths:
        return []
    projection = json_load(output / "markdown/projection.json")
    graph = json_load(output / "graph.json")
    title_by_id = {page["id"]: page["title"] for page in projection.get("pages", [])}
    owners = projection.get("entity_owner_pages", {})
    selectors: list[str] = []
    for entity in graph.get("entities", []):
        if str(entity.get("path", "")).replace("\\", "/") in selected_paths:
            owner = owners.get(entity["id"]) or (entity["id"] if entity["id"] in title_by_id else None)
            if owner in title_by_id:
                selectors.append(title_by_id[owner])
    selectors = list(dict.fromkeys(selectors))
    if selectors:
        return selectors
    repository_pages = [
        page["title"]
        for page in projection.get("pages", [])
        if page.get("page_type") == "repository"
    ]
    return repository_pages[:1]

def audit_notes(output: Path) -> list[dict[str, Any]]:
    root = output / "markdown"
    if not root.is_dir():
        return [{"reason": "markdown-vault-missing"}]
    projection = json_load(root / "projection.json")
    titles = {page["title"] for page in projection.get("pages", [])}
    notes = []
    errors: list[dict[str, Any]] = []
    for kind, directory_name in DIRECTORY_BY_KIND.items():
        directory = root / directory_name
        if not directory.is_dir():
            errors.append({"reason": "note-directory-missing", "directory": directory_name})
            continue
        for path in sorted(directory.glob("*.md")):
            text = path.read_text(encoding="utf-8")
            note_title = text.splitlines()[0].removeprefix("# ").strip() if text else ""
            notes.append(note_title)
            expected_tag = TAG_BY_KIND[kind]
            tags = re.findall(r"#类型/[\w\u3400-\u9fff-]+", text)
            if tags != [expected_tag]:
                errors.append({"reason": "note-tag-invalid", "path": str(path), "tags": tags, "expected": expected_tag})
            if text.startswith("---\n"):
                errors.append({"reason": "note-frontmatter-visible", "path": str(path)})
            if LONG_HEX.search(text):
                errors.append({"reason": "note-hash-visible", "path": str(path)})
            narrative = "\n".join(
                line
                for line in text.splitlines()
                if not line.startswith(("#", "标签：", "- [[", "- [打开源码："))
            )
            if not contains_chinese_narrative(narrative):
                errors.append({"reason": "note-description-not-chinese", "path": str(path)})
    all_titles = titles | set(notes)
    for directory_name in NOTE_DIRECTORIES:
        for path in (root / directory_name).glob("*.md"):
            text = path.read_text(encoding="utf-8")
            for target in re.findall(r"\[\[([^\]|#]+)", text):
                if target not in all_titles:
                    errors.append({"reason": "note-link-dangling", "path": str(path), "target": target})
    return errors

def workspace_status(output: Path) -> dict[str, Any]:
    state = json_load(output / "state.json")
    overlay = output / "workspace-meta/working-overlay.json"
    return {
        "schema_version": 1,
        "status": "ready",
        "baseline": {
            "status": (state.get("source_snapshot") or {}).get("status", "legacy-live-worktree"),
            "commit": state["repository"]["commit"],
            "snapshot_root": (state.get("source_snapshot") or {}).get("root"),
        },
        "working_overlay": json_load(overlay) if overlay.is_file() else {"status": "not-synced"},
        "notes": {"status": "passed" if not audit_notes(output) else "failed"} if (output / "markdown/projection.json").is_file() else {"status": "waiting-for-markdown"},
    }

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def validate_core_boundary() -> None:
    lite = {path.relative_to(ROOT).as_posix() for path in source_files(False)}
    full = {path.relative_to(ROOT).as_posix() for path in source_files(True)}
    missing = sorted(set(CORE_REQUIRED_FILES) - lite)
    if missing:
        raise RuntimeError(f"lite core capability files are absent: {missing}")
    if any(path == "plugins" or path.startswith("plugins/") for path in lite | full):
        raise RuntimeError("core distributions must not contain plugins/")
    if not lite < full:
        raise RuntimeError("full-win-x64 must strictly extend lite")
    unexpected = sorted(
        path for path in full - lite
        if not path.startswith("assets/runtime/win-x64/")
    )
    if unexpected:
        raise RuntimeError(f"full-win-x64 adds non-runtime files: {unexpected}")

def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path

def validate_plugin_dist() -> tuple[str, list[Path], dict]:
    dist = PLUGIN_ROOT / "dist"
    files = [dist / name for name in PLUGIN_FILES]
    missing = [path.name for path in files if not path.is_file() or path.stat().st_size == 0]
    if missing:
        raise RuntimeError(f"Obsidian plugin dist files are absent: {missing}")
    manifest = json.loads((dist / "manifest.json").read_text(encoding="utf-8"))
    version = manifest.get("version")
    if not isinstance(version, str) or not version.strip():
        raise RuntimeError("Obsidian plugin version is absent from manifest.json")
    build_record = json.loads((dist / "build-record.json").read_text(encoding="utf-8"))
    if build_record.get("status") != "passed":
        raise RuntimeError("Obsidian plugin build-record.json has not passed")
    recorded = {item["path"]: item for item in build_record.get("files", [])}
    for path in files:
        if path.name == "build-record.json":
            continue
        item = recorded.get(path.name)
        if not item:
            raise RuntimeError(f"Obsidian plugin build record is missing: {path.name}")
        if int(item.get("size", -1)) != path.stat().st_size or item.get("sha256") != sha256(path):
            raise RuntimeError(f"Obsidian plugin dist differs from build record: {path.name}")
    return version, files, build_record

def build_plugin(dist: Path) -> dict:
    version, files, build_record = validate_plugin_dist()
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder-obsidian",
        "version": version,
        "distribution": "obsidian-plugin",
        "category": "plugin",
        "requires": {
            "knowledge_base": "CKB output with machine/knowledge.sqlite",
            "core_package": "installed separately",
        },
        "bundled_core": False,
        "bundled_offline_runtime": False,
        "agent_deploy": {
            "standalone": "python deploy.py deploy --vault VAULT",
            "core": "ckb.py obsidian-plugin register/deploy/status/remove",
            "auto_deploy_after_registration": True,
        },
        "files": [
            {"path": path.name, "size": path.stat().st_size, "sha256": sha256(path)}
            for path in files
        ],
        "upstream_commit": build_record.get("claudian_commit"),
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-obsidian-{version}.zip"
    if archive_path.exists():
        archive_path.unlink()
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            info = zipfile.ZipInfo(path.name, date_time=(2026, 8, 30, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"Obsidian plugin ZIP CRC failed: {bad_member}")
        if archive.namelist() != list(PLUGIN_FILES):
            raise RuntimeError("Obsidian plugin ZIP member set or order differs")
        for path in files:
            if archive.read(path.name) != path.read_bytes():
                raise RuntimeError(f"Obsidian plugin ZIP bytes differ: {path.name}")
    result = {
        "status": "passed",
        "distribution": "obsidian-plugin",
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-obsidian-{version}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result

def build(kind: str, dist: Path) -> dict:
    if kind == "obsidian-plugin":
        return build_plugin(dist)
    return build_core(kind, dist)

def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--kind",
        choices=("lite", "full-win-x64", "obsidian-plugin", "both", "all"),
        required=True,
    )
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    if args.kind == "both":
        kinds = ("lite", "full-win-x64")
    elif args.kind == "all":
        kinds = ("lite", "full-win-x64", "obsidian-plugin")
    else:
        kinds = (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0
